// l5s4s: row-link modules and the final t2 glue.
// usage: rl_gen <dir with recd_<k>.tsv, k = 0..25> <rep list file (one class id per line = reps whose GD3N<c> module is built)> <out dir> <reps per module>
// Per depth-1 node k (class ids c = clsFirst .. clsFirst+size-1, position i = c - clsFirst) and for every listed rep c a theorem
//   rl_<c> : N<c>.nK.rows = setRow T2D<k>.nK.rows 1 (cY ((T2D<k>.flatN.map unpackRec).getD (<P>.repPos.getD i 0) []))   (P = T2D<k> or T2E<k>)
// in modules T2RL<k>_<j> (at most `per` reps each), a status table, and T2Final (t2_all: the per-node statements over R1d1).
use std::collections::BTreeSet;
use std::fs;

fn main() {
    let a: Vec<String> = std::env::args().collect();
    if a.len() < 5 { eprintln!("usage: rl_gen <recd dir> <replist> <outdir> <per>"); std::process::exit(2); }
    let dir = &a[1]; let outd = &a[3]; let per: usize = a[4].parse().unwrap();
    let built: BTreeSet<usize> = fs::read_to_string(&a[2]).unwrap().split_whitespace().map(|x| x.parse().unwrap()).collect();
    let pre = |k: usize| -> &'static str { if k == 1 || k == 5 || k == 19 { "T2E" } else { "T2D" } };
    let mut status = String::from("node\tclsFirst\tsize\tlinked\tmissing\n");
    let mut mods: Vec<String> = vec![];
    let mut first = vec![0usize; 26]; let mut size = vec![0usize; 26];
    let mut tot = 0usize; let mut totl = 0usize;
    for k in 0..26usize {
        let t = fs::read_to_string(format!("{}/recd_{}.tsv", dir, k)).unwrap();
        let ids: Vec<usize> = t.lines().filter(|l| !l.is_empty()).map(|l| l.split(' ').next().unwrap().parse().unwrap()).collect();
        for w in ids.windows(2) { assert_eq!(w[1], w[0] + 1, "class ids of a node must be consecutive"); }
        first[k] = ids.first().cloned().unwrap_or(0); size[k] = ids.len(); tot += ids.len();
        let lk: Vec<(usize, usize)> = ids.iter().enumerate().filter(|(_, c)| built.contains(c)).map(|(i, c)| (i, *c)).collect();
        totl += lk.len();
        let miss: Vec<usize> = ids.iter().cloned().filter(|c| !built.contains(c)).collect();
        status.push_str(&format!("{}\t{}\t{}\t{}\t{}\n", k, first[k], ids.len(), lk.len(), miss.len()));
        // chunking by POSITION (i / per) keeps the module boundaries stable while the rollout adds reps
        let nm = (ids.len() + per - 1) / per;
        for j in 0..nm {
            let modn = format!("T2RL{}_{}", k, j);
            let chunk: Vec<(usize, usize)> = lk.iter().cloned().filter(|(i, _)| i / per == j).collect();
            if chunk.is_empty() { continue; }
            let chunk = &chunk[..];
            let mut s = format!("/-\n# L5S4.{} : row links of the class leaders of depth-1 node #{} to the rollout nodes (stage S4S)\n\nFor every listed rep `c`, the rollout node `N<c>.nK` has the rows `setRow nK.rows 1 (cY leader)` of the leader record at\n`repPos[c - clsFirst]` of the node (the hypothesis `hrows` of `t2_block`).  Generated by l5s4s `rl_gen`.\nNo `sorry`, no `native_decide`, no new axiom.  Not registered in any aggregator.\n-/\n", modn, k);
            s.push_str(&format!("import LRSpectrumFull.L5S4.{}{}Pos\n", pre(k), k));
            for (_, c) in chunk { s.push_str(&format!("import LRSpectrumFull.L5S4.GD3N{}\n", c)); }
            s.push_str("\nnamespace LRSpectrumFull\nnamespace L5S4\n\nopen Matrix Finset LRSpectrumFull.L5S3\n\nset_option maxRecDepth 100000\n\n");
            for (i, c) in chunk {
                s.push_str(&format!("theorem rl_{c} : N{c}.nK.rows =\n    setRow T2D{k}.nK.rows 1 (cY ((T2D{k}.flatN.map unpackRec).getD ({p}{k}.repPos.getD {i} 0) [])) := by decide +kernel\n", c = c, k = k, i = i, p = pre(k)));
            }
            if ids.len() >= 2 {
                let (i, c) = chunk[0]; let i2 = if i + 1 < ids.len() { i + 1 } else { i - 1 };
                s.push_str(&format!("\n/-- control: the neighbouring position does not match (the link is not vacuous). -/\ntheorem ctl_{m}_nb : ¬ (N{c}.nK.rows =\n    setRow T2D{k}.nK.rows 1 (cY ((T2D{k}.flatN.map unpackRec).getD ({p}{k}.repPos.getD {i2} 0) []))) := by decide +kernel\n", m = modn, c = c, k = k, i2 = i2, p = pre(k)));
            }
            s.push_str("\n");
            for (_, c) in chunk { s.push_str(&format!("#print axioms rl_{}\n", c)); }
            if ids.len() >= 2 { s.push_str(&format!("#print axioms ctl_{}_nb\n", modn)); }
            s.push_str("\nend L5S4\nend LRSpectrumFull\n");
            fs::write(format!("{}/{}.lean", outd, modn), s).unwrap(); mods.push(modn);
        }
    }
    fs::write(format!("{}/T2RL.mods", outd), mods.join("\n") + "\n").unwrap();
    fs::write(format!("{}/T2RL_STATUS.tsv", outd), &status).unwrap();
    // final glue
    let mut s = String::from("/-\n# L5S4.T2Final : `StreamHyp'.t2` over `R1d1` from the 26 per-node blocks and the row links (stage S4S)\n\n`t2_all`: for ANY map `node : ℕ → NodeW 2 3` (the rollout nodes by global class id) with `node c ∈ R2` for `c < 1965`, if for every depth-1 node `k` the row\nlink `Lk<k> node` holds (the rollout node of class `clsFirst + i` has the rows `setRow nK.rows 1 (cY leader_i)`), then `T2Stmt n R2` holds for every\n`n ∈ R1d1`.  The 26 hypotheses `Lk<k>` are discharged rep by rep by the modules `T2RL<k>_<j>` (theorems `rl_<c>`); the reps without a built\n`GD3N<c>` module are listed in `T2RL_STATUS.tsv`.  Generated by l5s4s `rl_gen`.\n\nNo `sorry`, no `native_decide`, no new axiom.  Not registered in any aggregator.\n-/\nimport LRSpectrumFull.L5S4.T2All\n");
    for k in 0..26 { s.push_str(&format!("import LRSpectrumFull.L5S4.{}{}Pos\n", pre(k), k)); }
    s.push_str("\nnamespace LRSpectrumFull\nnamespace L5S4\nnamespace T2Final\n\nopen Matrix Finset LRSpectrumFull.L5S3\n\nset_option maxRecDepth 100000\n\n");
    for k in 0..26 {
        s.push_str(&format!("/-- the row link of depth-1 node #{k} -/\ndef Lk{k} (node : ℕ → NodeW 2 3) : Prop :=\n  ∀ i, i < {p}{k}.repPos.length → (node ({p}{k}.clsFirst + i)).rows =\n    setRow T2D{k}.nK.rows 1 (cY ((T2D{k}.flatN.map unpackRec).getD ({p}{k}.repPos.getD i 0) []))\n\n", k = k, p = pre(k)));
    }
    s.push_str("theorem sub_of (node : ℕ → NodeW 2 3) (R2 : Set (NodeW 2 3)) (hmem : ∀ c, c < 1965 → node c ∈ R2) (f len : ℕ) (hle : f + len ≤ 1965) :\n    {a | ∃ i, i < len ∧ a = node (f + i)} ⊆ R2 := by\n  rintro a ⟨i, hi, rfl⟩\n  exact hmem _ (by omega)\n\n");
    s.push_str("theorem t2_all (R2 : Set (NodeW 2 3)) (node : ℕ → NodeW 2 3) (hmem : ∀ c, c < 1965 → node c ∈ R2)\n");
    for k in 0..26 { s.push_str(&format!("    (h{k} : Lk{k} node)\n", k = k)); }
    s.push_str("    : ∀ n ∈ R1d1, T2Stmt n R2 := by\n  apply t2_of_d1\n  intro i hi hr\n  rw [d1Data_length] at hi\n  interval_cases i\n");
    for k in 0..26 { s.push_str(&format!("  · exact T2Stmt.mono ({p}{k}.t2_block (fun i => node ({p}{k}.clsFirst + i)) h{k}) (sub_of node R2 hmem _ _ (by decide +kernel))\n", k = k, p = pre(k))); }
    s.push_str("\ntheorem sizes_total : T2D0.repPos.length");
    for k in 1..26 { s.push_str(&format!(" + {}{}.repPos.length", pre(k), k)); }
    s.push_str(&format!(" = {} := by decide +kernel\n\n", tot));
    s.push_str("theorem t2all_ctl_sorry : (1 : ℕ) = 2 := by sorry\n\n#print axioms t2_all\n#print axioms sizes_total\n#print axioms t2all_ctl_sorry\n\nend T2Final\nend L5S4\nend LRSpectrumFull\n");
    fs::write(format!("{}/T2Final.lean", outd), s).unwrap();
    println!("rl_gen: {} classes in 26 nodes, {} linked ({} modules), final glue written", tot, totl, mods.len());
}
